// Port of simulation.py (model v0.2) / experiment.py for the browser and Node. ES module, no dependencies.
//
// The PRNG is a bit-exact port of CPython's random.Random (MT19937, init_by_array seeding,
// 53-bit random(), getrandbits-based choice, cached-pair gauss), so that for the same seed this
// module and the Python simulator draw the same numbers. test_parity.mjs checks that against
// fixtures generated by the Python code. Keep the order of every rng call identical to Python.

// ---------------------------------------------------------------- PRNG (CPython-compatible)
const N = 624, M = 397, MATRIX_A = 0x9908b0df, UPPER = 0x80000000, LOWER = 0x7fffffff;
const TWOPI = 2 * Math.PI;

export class PyRandom {
  constructor(seed) {
    this.mt = new Uint32Array(N);
    this.mti = N + 1;
    this.gaussNext = null;
    this.seed(seed);
  }

  seed(n) {
    if (!Number.isSafeInteger(n)) throw new Error('seed must be a safe integer');
    n = Math.abs(n);
    const key = [n % 4294967296];
    const hi = Math.floor(n / 4294967296);
    if (hi > 0) key.push(hi); // seeds < 2^53 need at most two 32-bit words
    this.#initByArray(key);
  }

  #initGenrand(s) {
    const mt = this.mt;
    mt[0] = s >>> 0;
    for (let i = 1; i < N; i++) {
      const prev = mt[i - 1] ^ (mt[i - 1] >>> 30);
      mt[i] = (Math.imul(1812433253, prev) + i) >>> 0;
    }
    this.mti = N;
  }

  #initByArray(key) {
    const mt = this.mt;
    this.#initGenrand(19650218);
    let i = 1, j = 0;
    for (let k = Math.max(N, key.length); k > 0; k--) {
      const prev = mt[i - 1] ^ (mt[i - 1] >>> 30);
      mt[i] = ((mt[i] ^ Math.imul(prev, 1664525)) + key[j] + j) >>> 0;
      i++; j++;
      if (i >= N) { mt[0] = mt[N - 1]; i = 1; }
      if (j >= key.length) j = 0;
    }
    for (let k = N - 1; k > 0; k--) {
      const prev = mt[i - 1] ^ (mt[i - 1] >>> 30);
      mt[i] = ((mt[i] ^ Math.imul(prev, 1566083941)) - i) >>> 0;
      i++;
      if (i >= N) { mt[0] = mt[N - 1]; i = 1; }
    }
    mt[0] = 0x80000000;
    this.gaussNext = null;
  }

  #genrand() {
    const mt = this.mt;
    if (this.mti >= N) {
      let kk = 0, y;
      for (; kk < N - M; kk++) {
        y = (mt[kk] & UPPER) | (mt[kk + 1] & LOWER);
        mt[kk] = mt[kk + M] ^ (y >>> 1) ^ ((y & 1) ? MATRIX_A : 0);
      }
      for (; kk < N - 1; kk++) {
        y = (mt[kk] & UPPER) | (mt[kk + 1] & LOWER);
        mt[kk] = mt[kk + (M - N)] ^ (y >>> 1) ^ ((y & 1) ? MATRIX_A : 0);
      }
      y = (mt[N - 1] & UPPER) | (mt[0] & LOWER);
      mt[N - 1] = mt[M - 1] ^ (y >>> 1) ^ ((y & 1) ? MATRIX_A : 0);
      this.mti = 0;
    }
    let y = mt[this.mti++];
    y ^= y >>> 11;
    y ^= (y << 7) & 0x9d2c5680;
    y ^= (y << 15) & 0xefc60000;
    y ^= y >>> 18;
    return y >>> 0;
  }

  random() {
    const a = this.#genrand() >>> 5, b = this.#genrand() >>> 6;
    return (a * 67108864 + b) * (1 / 9007199254740992);
  }

  getrandbits(k) { return this.#genrand() >>> (32 - k); } // 1 <= k <= 32

  randbelow(n) {
    const k = 32 - Math.clz32(n);
    let r = this.getrandbits(k);
    while (r >= n) r = this.getrandbits(k);
    return r;
  }

  choice(arr) { return arr[this.randbelow(arr.length)]; }
  uniform(a, b) { return a + (b - a) * this.random(); }

  gauss(mu = 0, sigma = 1) {
    let z = this.gaussNext;
    this.gaussNext = null;
    if (z === null) {
      const x2pi = this.random() * TWOPI;
      const g2rad = Math.sqrt(-2.0 * Math.log(1.0 - this.random()));
      z = Math.cos(x2pi) * g2rad;
      this.gaussNext = Math.sin(x2pi) * g2rad;
    }
    return mu + z * sigma;
  }
}

// ---------------------------------------------------------------- model definitions
export const TRADITIONAL = {
  name: 'Traditional', capacity: 100, monthly_staff_cost: 205000, ai_tool_cost: 6000,
  token_cost_per_work: 15, defect_factor: 1.0, decision_cadence: 3, review_strength: 0.80,
};
export const AI_NATIVE = {
  name: 'AI-native', capacity: 135, monthly_staff_cost: 150000, ai_tool_cost: 32000,
  token_cost_per_work: 200, defect_factor: 1.35, decision_cadence: 1, review_strength: 0.55,
};

// Coefficients both firms share. Defaults are the v0.1 values (mirror of simulation.Assumptions).
export const DEFAULT_ASSUMPTIONS = {
  arpu: 82, overhead: 35000, cost_per_customer: 8, start_cash: 2500000,
  debt_per_build: .068, review_effect: .40, throttle_start: 20, debt_threshold: 28,
  churn_base: .014, downturn_start: 0, downturn_months: 0, downturn_mult: 1.0,
};

const scenario = (name, o = {}) => ({
  name, native_capacity_mult: 1.0, native_defect_mult: 1.0, native_tool_mult: 1.0,
  native_review_delta: 0.0, market_growth_mult: 1.0, compliance_shocks: true, ...o,
});
export const SCENARIOS = {
  'baseline': scenario('baseline'),
  'ai-friction': scenario('ai-friction', { native_capacity_mult: 0.85, native_defect_mult: 1.5, native_tool_mult: 1.65 }),
  'ai-mature': scenario('ai-mature', { native_capacity_mult: 1.12, native_defect_mult: 0.75, native_review_delta: 0.15 }),
  'slow-market': scenario('slow-market', { market_growth_mult: 0.55 }),
};
const INITIAL_ALLOCATION = { discover: .16, build: .36, harden: .21, grow: .16, govern: .11 };

// ---------------------------------------------------------------- simulation
const clamp = (x, lo, hi) => Math.min(Math.max(x, lo), hi);

function newFirm(model, cash = 2500000) {
  return {
    model, customers: 3500, cash, product: 49, fit: 48, debt: 18, trust: 72,
    governance: 66, lastAllocation: { ...INITIAL_ALLOCATION }, incidents: 0, badBuilds: 0,
    cumulativeProfit: 0, deliveredWork: 0, alive: true, minCash: cash,
  };
}

function chooseAllocation(firm, month, event, rng) {
  if ((month - 1) % firm.model.decision_cadence !== 0) return { ...firm.lastAllocation };
  const a = { ...INITIAL_ALLOCATION };
  if (event === 'new-demand') Object.assign(a, { discover: .23, build: .43, harden: .15, grow: .12, govern: .07 });
  else if (event === 'compliance') Object.assign(a, { discover: .09, build: .21, harden: .25, grow: .10, govern: .35 });
  else if (event === 'outage') Object.assign(a, { discover: .08, build: .21, harden: .44, grow: .10, govern: .17 });
  else if (event === 'price-pressure') Object.assign(a, { discover: .12, build: .33, harden: .20, grow: .25, govern: .10 });
  const vals = {};
  for (const k of Object.keys(a)) vals[k] = Math.max(.025, a[k] + rng.gauss(0, .015));
  const s = Object.values(vals).reduce((x, y) => x + y, 0);
  const out = {};
  for (const k of Object.keys(vals)) out[k] = vals[k] / s;
  return out;
}

const EVENTS_BASE = [
  ...Array(72).fill('normal'), ...Array(9).fill('new-demand'),
  ...Array(7).fill('outage'), ...Array(8).fill('price-pressure'),
];
const EVENTS_COMPLIANCE = [...EVENTS_BASE, ...Array(4).fill('compliance')];

// Pure formulas (mirrors of simulation.py). Exported so test_parity.mjs can sweep them on a grid.
export const debtPenalty = (debt, throttleStart = 20) => clamp(1 - Math.max(0, debt - throttleStart) * .0045, .40, 1.0);

export function badBuildProbability(governance, fit, review, event) {
  let p = .008 + Math.max(0, 60 - governance) * .0018 + Math.max(0, 55 - fit) * .0008 + (1 - review) * .027;
  if (event === 'compliance') p += .045;
  return p;
}

export function incidentProbability(debt, governance, event, badBuild, threshold = 28) {
  let risk = .012 + Math.max(0, debt - threshold) * .0022 + Math.max(0, 55 - governance) * .0015;
  if (event === 'outage') risk += .13;
  if (badBuild) risk += .08;
  return Math.min(.45, risk);
}

export const churnRate = (trust, debt, incident, base = .014, threshold = 28) =>
  clamp(base + Math.max(0, 65 - trust) * .00048 + Math.max(0, debt - threshold) * .00018 + (incident ? 0.012 : 0), .004, .14);

function eventForMonth(rng, sc) {
  return rng.choice(sc.compliance_shocks ? EVENTS_COMPLIANCE : EVENTS_BASE);
}

function applyOperations(firm, month, event, sc, rng, a) {
  if (!firm.alive) return { work: 0, incident: false, badBuild: false, cost: 0 };
  const native = firm.model.name === 'AI-native';
  const allocation = chooseAllocation(firm, month, event, rng);
  firm.lastAllocation = allocation;

  const capMult = native ? sc.native_capacity_mult : 1.0;
  const defectMult = native ? sc.native_defect_mult : 1.0;
  const review = clamp(firm.model.review_strength + (native ? sc.native_review_delta : 0), 0, 1);
  const work = Math.max(0, firm.model.capacity * capMult * debtPenalty(firm.debt, a.throttle_start) * clamp(rng.gauss(1, .065), .7, 1.3));
  const units = {};
  for (const k of Object.keys(allocation)) units[k] = work * allocation[k];
  firm.deliveredWork += work;

  firm.fit = clamp(firm.fit + units.discover * .068 * (100 - firm.fit) / 60, 0, 100);
  let buildValue = units.build * (.047 + (firm.fit - 45) * .00028);
  if (event === 'new-demand') buildValue *= 1.30;
  firm.product = clamp(firm.product + buildValue * (100 - firm.product) / 65, 0, 100);

  const reviewModifier = 1.15 - a.review_effect * review;
  const newDebt = units.build * a.debt_per_build * firm.model.defect_factor * defectMult * reviewModifier;
  firm.debt = clamp(firm.debt + newDebt - units.harden * .105, 0, 100);
  firm.governance = clamp(firm.governance + units.govern * .078 - units.build * .017, 0, 100);

  const badBuild = rng.random() < badBuildProbability(firm.governance, firm.fit, review, event);
  if (badBuild) {
    firm.badBuilds += 1;
    firm.debt = clamp(firm.debt + 5, 0, 100);
    firm.trust = clamp(firm.trust - 3, 0, 100);
  }

  const incident = rng.random() < incidentProbability(firm.debt, firm.governance, event, badBuild, a.debt_threshold);
  if (incident) {
    firm.incidents += 1;
    firm.trust = clamp(firm.trust - rng.uniform(4, 10), 0, 100);
    firm.debt = clamp(firm.debt + rng.uniform(1, 4), 0, 100);
  } else {
    firm.trust = clamp(firm.trust + units.harden * .017 + units.govern * .012, 0, 100);
  }

  let penalty = 0;
  if (event === 'compliance' && firm.governance < 65) {
    penalty = (65 - firm.governance) * 3500;
    firm.trust = clamp(firm.trust - 2.0, 0, 100);
  }
  if (badBuild) penalty += 30000;
  if (incident) penalty += rng.uniform(25000, 100000);

  const tokenMult = native ? sc.native_tool_mult : 1.0;
  const cost = firm.model.monthly_staff_cost + a.overhead + firm.customers * a.cost_per_customer +
    firm.model.ai_tool_cost * tokenMult + work * firm.model.token_cost_per_work * tokenMult + penalty;
  return { work, incident, badBuild, cost, growthSpend: units.grow };
}

function attractiveness(firm, growthSpend) {
  if (!firm.alive) return 0;
  return .39 * firm.product + .19 * firm.fit + .23 * firm.trust +
    .14 * (100 - firm.debt) + .05 * clamp(growthSpend * 2.5, 0, 100);
}

function row(seed, month, sc, event, f, profit, revenue, cost, work) {
  return {
    seed, month, scenario: sc.name, event, company: f.model.name, customers: f.customers,
    cash_gbp: f.cash, monthly_profit_gbp: profit, revenue_gbp: revenue, cost_gbp: cost,
    product: f.product, fit: f.fit, debt: f.debt, trust: f.trust, governance: f.governance,
    work, incidents_cumulative: f.incidents, bad_builds_cumulative: f.badBuilds, alive: f.alive,
  };
}

/** One paired run. Returns { firms: [slot0, slot1], history } (history is unrounded). */
export function runOnce(seed, months, sc, { keepHistory = false, models = null, assumptions = DEFAULT_ASSUMPTIONS } = {}) {
  const a = assumptions;
  const marketRng = new PyRandom(seed);
  const rngs = [new PyRandom(seed * 73 + 11), new PyRandom(seed * 73 + 29)];
  const [m0, m1] = models ?? [AI_NATIVE, TRADITIONAL];
  const firms = [newFirm(m0, a.start_cash), newFirm(m1, a.start_cash)];
  const history = [];
  for (let month = 1; month <= months; month++) {
    const event = eventForMonth(marketRng, sc);
    let marketDemand = Math.max(0, marketRng.gauss(480, 125)) * sc.market_growth_mult;
    if (a.downturn_months && a.downturn_start <= month && month < a.downturn_start + a.downturn_months) marketDemand *= a.downturn_mult;
    if (event === 'new-demand') marketDemand *= 1.4;
    if (event === 'price-pressure') marketDemand *= .75;
    const ops = firms.map((f, i) => applyOperations(f, month, event, sc, rngs[i], a));
    const scores = firms.map((f, i) => attractiveness(f, ops[i].growthSpend ?? 0));
    const weights = firms.map((f, i) => (f.alive ? Math.exp((scores[i] - 60) / 17) : 0));
    const denominator = weights[0] + weights[1] + 0.8;
    const newCustomers = weights.map(w => marketDemand * w / denominator);

    const churnLost = firms.map((f, i) => {
      if (!f.alive) return 0;
      return f.customers * churnRate(f.trust, f.debt, ops[i].incident, a.churn_base, a.debt_threshold);
    });
    const switched = [firms[0].alive ? churnLost[1] * .20 : 0, firms[1].alive ? churnLost[0] * .20 : 0];

    firms.forEach((f, i) => {
      if (!f.alive) {
        if (keepHistory) history.push(row(seed, month, sc, event, f, 0, 0, 0, 0));
        return;
      }
      f.customers = Math.max(0, f.customers - churnLost[i] + newCustomers[i] + switched[i]);
      const revenue = f.customers * a.arpu;
      const profit = revenue - ops[i].cost;
      f.cash += profit;
      f.cumulativeProfit += profit;
      if (f.cash <= 0) { f.cash = 0; f.alive = false; }
      f.minCash = Math.min(f.minCash, f.cash);
      if (keepHistory) history.push(row(seed, month, sc, event, f, profit, revenue, ops[i].cost, ops[i].work));
    });
  }
  return { firms, history };
}

// ---------------------------------------------------------------- statistics helpers
export const mean = xs => xs.reduce((a, b) => a + b, 0) / xs.length;
export function median(xs) {
  const s = [...xs].sort((a, b) => a - b), n = s.length;
  return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
}
export function stdev(xs) {
  const m = mean(xs);
  return Math.sqrt(xs.reduce((a, x) => a + (x - m) ** 2, 0) / (xs.length - 1));
}
/** Python-style round(x, nd): round-half-even on exact ties. */
export function pyRound(x, nd = 0) {
  // toFixed works on the exact binary value, so it is correct except on *exact* ties (JS rounds those
  // up, Python to even). Detect an exact tie from the exact decimal expansion, not from x * 10**nd,
  // which can land on .5 by rounding error (0.685 * 100 === 68.5, but 0.685 is really 0.68500000000000005).
  const frac = Math.abs(x).toFixed(Math.min(100, nd + 40)).split('.')[1] ?? '';
  if (/^50*$/.test(frac.slice(nd))) {
    const m = 10 ** nd, y = x * m, fl = Math.floor(y); // exact: a representable tie times 10**nd is exact
    return (fl % 2 === 0 ? fl : fl + 1) / m;
  }
  return Number(x.toFixed(nd));
}

/** Port of simulation.monte_carlo: same summary keys and rounding as the Python output. */
export function monteCarlo(runs, months, sc, seed = 42, models = null, assumptions = DEFAULT_ASSUMPTIONS) {
  const rows = [];
  for (let i = 0; i < runs; i++) {
    const { firms } = runOnce(seed + i, months, sc, { models, assumptions });
    rows.push({
      nCash: firms[0].cash, tCash: firms[1].cash, nCust: firms[0].customers, tCust: firms[1].customers,
      nInc: firms[0].incidents, tInc: firms[1].incidents, nBad: firms[0].badBuilds, tBad: firms[1].badBuilds,
      nSurv: +firms[0].alive, tSurv: +firms[1].alive, nWork: firms[0].deliveredWork, tWork: firms[1].deliveredWork,
    });
  }
  const col = k => rows.map(r => r[k]);
  const cashWins = rows.filter(r => r.nCash > r.tCash).length;
  return {
    scenario: sc.name, runs, months, seed_start: seed,
    ai_native_cash_win_fraction: pyRound(cashWins / runs, 3),
    cash_ties: rows.filter(r => r.nCash === r.tCash).length,
    median_final_cash_gbp: { 'AI-native': pyRound(median(col('nCash'))), Traditional: pyRound(median(col('tCash'))) },
    median_customers: { 'AI-native': pyRound(median(col('nCust'))), Traditional: pyRound(median(col('tCust'))) },
    mean_incidents: { 'AI-native': pyRound(mean(col('nInc')), 2), Traditional: pyRound(mean(col('tInc')), 2) },
    mean_bad_builds: { 'AI-native': pyRound(mean(col('nBad')), 2), Traditional: pyRound(mean(col('tBad')), 2) },
    survival_fraction: { 'AI-native': pyRound(mean(col('nSurv')), 3), Traditional: pyRound(mean(col('tSurv')), 3) },
    median_work_units: { 'AI-native': pyRound(median(col('nWork'))), Traditional: pyRound(median(col('tWork'))) },
  };
}

/** Port of experiment.paired: slot0 (AI-native by default) vs slot1 on identical seeds. */
export function paired(models, sc = SCENARIOS.baseline, runs = 1000, months = 36, seed = 42, assumptions = DEFAULT_ASSUMPTIONS) {
  const diffs = [];
  let wins = 0, inc0 = 0, inc1 = 0, cust0 = 0, cust1 = 0;
  for (let i = 0; i < runs; i++) {
    const { firms } = runOnce(seed + i, months, sc, { models, assumptions });
    const d = firms[0].cash - firms[1].cash;
    diffs.push(d);
    if (d > 0) wins++;
    inc0 += firms[0].incidents; inc1 += firms[1].incidents;
    cust0 += firms[0].customers; cust1 += firms[1].customers;
  }
  const p = wins / runs;
  return {
    runs,
    win_fraction: p,
    win_ci95: 1.96 * Math.sqrt(p * (1 - p) / runs),
    mean_cash_diff: mean(diffs),
    mean_cash_diff_ci95: 1.96 * stdev(diffs) / Math.sqrt(runs),
    median_cash_diff: median(diffs),
    mean_incidents_slot0: inc0 / runs,
    mean_incidents_slot1: inc1 / runs,
    mean_customers_slot0: cust0 / runs,
    mean_customers_slot1: cust1 / runs,
    diffs, // per-run final cash gap (slot0 - slot1), for histograms
  };
}
